// src/features/catalog/api/catalogApi.ts
import { request } from "../../../shared/http/request";
import type { CourseCardProps } from "../components/CourseCard";

export function fetchCourses(params: CourseListParams): Promise<CourseCardProps["course"][]> {
  return request(`/courses${toQuery(params)}`, { signal: params.signal });
}

Statement: "Because of the second import, renaming or reshaping the course prop of CourseCard can force a change in the API module, so this dependency points the wrong way."', 'single_choice'::question_type, 'True. The API module takes its return type from a presentational component, so the arrow goes api -> components, the opposite of components -> hooks -> api. A purely visual change to CourseCard''s props now changes the type of fetchCourses and every caller of it, and a reviewer of a UI change must also review the data layer. The fix is to define Course in the API module (it describes what the server returns) and let CourseCard import it. The misconception is that `import type` is harmless because it disappears at runtime: it is erased from the JavaScript, but it still couples the two files at compile time, which is where the change has to be made.', 2, 5
