-- challenge chal_coding_trf_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_trf_122', (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-trf-1-2' AND is_deleted = false LIMIT 1), 'derive-catalog-ui-state', 'Derive the catalog''s UI state', 'The CodeDev catalog page used three booleans and showed "No courses found" while it was still loading and a blank page when the API failed. Its query hook now gives a request snapshot { status: "pending" | "error" | "success", isFetching, query, data?, error? } (error = { status, message }, status 0 for a network error or timeout). Write deriveUiState(snapshot), which returns exactly one of { kind: "loading" } | { kind: "error", message, canRetry } | { kind: "empty", query } | { kind: "success", courses, refreshing }. Rules, in order: status "pending" is loading. Status "error": a 401 gives the message "Your session has expired. Sign in again." and canRetry false; status 0, 408, 429 or 500-599, or no error object at all, gives "Could not load courses. Try again." and canRetry true; any other status gives the API''s error.message and canRetry false. Status "success" with data missing or empty is empty, with the query trimmed; with courses it is success, with courses = data and refreshing = isFetching, so a background refetch keeps the list on screen. The test runner reads a list of snapshots as JSON and prints the UI state of each, with courses shown as their ids.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
