    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_trf_131');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_trf_131'), 'Two components on the catalog page read the same query:

// NewestTab.tsx
const { data = [] } = useQuery({ queryKey: ["courses"], queryFn: fetchCourses });
const newest = data.sort((a, b) => b.publishedAt.localeCompare(a.publishedAt));

// TopRatedSidebar.tsx
const { data = [] } = useQuery({ queryKey: ["courses"], queryFn: fetchCourses });
const top = data.slice(0, 5);

The API returns the courses ordered by rating. NewestTab renders first.

Statement: "After NewestTab renders, the array TopRatedSidebar reads is in newest-first order too, because both components received the same array object from the cache."', 'single_choice'::question_type, 'True. Both useQuery calls share the key ["courses"], so they return the same cached array object, and Array.prototype.sort reorders that array in place and returns it. NewestTab has therefore rewritten the cache entry: the sidebar''s slice(0, 5) now takes the five newest courses, not the five best rated. Because React was not told about the change, the sidebar may show the wrong order only after its next re-render, which makes the bug look intermittent. The fix is to sort a copy ([...data].sort(...) or data.toSorted(...)) inside a pure function. The misconception is that data from a hook is a private copy for each component; with a shared cache it is shared state.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_trf_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_trf_131'), 'The Top rated tab paginates with:

const sorted = [...courses].sort((a, b) => b.rating - a.rating);
const pageItems = sorted.slice((page - 1) * 2, page * 2);   // 2 per page

Two responses of GET /courses, one before and one after a background refetch (same courses, different order):

response 1: c07 (4.8), c03 (4.9), c11 (4.8), c02 (4.6)
response 2: c03 (4.9), c11 (4.8), c02 (4.6), c07 (4.8)

A learner loads page 1 from response 1, the refetch lands, then the learner opens page 2.

Statement: "Because Array.prototype.sort is stable, this code produces the same order from both responses, so page 2 cannot repeat a course from page 1."', 'single_choice'::question_type, 'False. A stable sort keeps tied elements in their input order, and the input order is different in the two responses. Response 1 sorts to c03, c07, c11, c02 (c07 came before c11); response 2 sorts to c03, c11, c07, c02. Page 1 from response 1 is c03, c07; page 2 from response 2 is c07, c02: c07 appears twice and c11 is never shown. Stability guarantees consistency for one input, not across inputs. The fix is a total order: end the comparator with a unique key, for example `|| (a.id < b.id ? -1 : 1)`, so ties come out the same way whatever order the API used. The misconception is that "stable" means "deterministic for the same set of items".', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_trf_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_trf_132 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_trf_132', (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-trf-1-3' AND is_deleted = false LIMIT 1), 'catalog-filter-sort-paginate', 'Filter, sort and paginate the catalog', 'The CodeDev catalog page sorted the cached course list with .sort() during render, so the "Newest" tab also reordered the "Top rated" sidebar, and tied courses moved between pages after a refetch. Write selectCatalogPage(courses, query) as a pure function. Search: query.search trimmed and case-insensitive, kept when the title contains it; an empty search keeps everything. Filters: category and level must equal the query''s values, "all" turns a filter off. Sort: "rating" highest first, "newest" latest publishedAt first (ISO dates, compare as strings), "title" A to Z by title.toLowerCase() compared with < and >; ties are ordered by id A to Z. Paginate: total = matching courses, totalPages = Math.ceil(total / pageSize) but at least 1, the page clamped into 1..totalPages, items = that page''s courses. Return { items, page, totalPages, total } and never change the courses array or its courses. The test runner reads { courses, queries } as JSON, runs every query on the same array in order, and prints each page (items as ids) and whether the array is unchanged at the end.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
