WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-trf-2-2' AND is_deleted = false);

-- challenge chal_quiz_trf_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_trf_221', (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-trf-2-2' AND is_deleted = false LIMIT 1), 'derived-state-quiz', 'Copy or compute? Read the catalog''s state', 'Three pieces of evidence from the catalog: a filtered list that missed a new course, a details panel after a rename, and a Profiler measurement someone wants to fix with useMemo.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
