-- challenge chal_coding_trf_412 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_trf_412', (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-trf-4-1' AND is_deleted = false LIMIT 1), 'typed-api-result', 'Typed API layer: from a recorded response to a Result', 'The catalog page used to read GET https://api.codedev.test/courses with `(await res.json()) as Course[]`. When the API renamed rating to averageRating, the cast still compiled and CourseCard crashed with "Cannot read properties of undefined (reading ''toFixed'')". Write toResult(recorded), the one place where the API layer turns what fetch gave it into Result<Course[]> = { ok: true; data: Course[] } | { ok: false; error: ApiError }, with ApiError = { kind: "network" } | { kind: "timeout" } | { kind: "http"; status; message } | { kind: "invalid-response"; reason }. A recording is either { error: { name, message } } (fetch rejected) or { status, headers, body } (body is the raw text). Rules, in this order: (1) a rejected fetch is { kind: "timeout" } when error.name is "TimeoutError", otherwise { kind: "network" }. (2) A status outside 200-299 is { kind: "http", status, message }: when the content-type header (header names are case-insensitive) starts with application/problem+json and the body parses to an object, message is its detail if that is a string, else its title if that is a string; in every other case message is "HTTP <status>". (3) 204 is { ok: true, data: [] } (there is no body to parse). (4) Any other 2xx: a body that is empty or only whitespace gives reason "empty body"; a body JSON.parse rejects gives "body is not JSON"; a value that is not an array gives "expected an array". (5) Each element i, in array order: anything that is not a plain object (null and arrays included) gives "courses[i] is not an object"; otherwise the fields are checked in this order and the first bad one gives "courses[i].<field> is invalid": id a non-empty string, title a string, category one of react, node, sql, python, devops, level one of beginner, intermediate, advanced, rating a finite number from 0 to 5, enrolled an integer >= 0, publishedAt a string. One bad element makes the whole response invalid. (6) Otherwise { ok: true, data } where each course has exactly the seven Course fields: drop any extra property the API sends. Parse the body as unknown and check it; do not cast. The runner reads a list of recordings and prints the list of results as JSON.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_412');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_412'), 1, 'Before you look at a single field: which questions does the API layer have to answer, in which order, to know whether there is anything to parse at all? A rejected fetch, an error status and a 204 never reach JSON.parse.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_412'), 2, 'Look at three places: the content-type header (find it by comparing the header names in lower case, then compare the start of the value), the status range, and a small function parseCourse(value: unknown, i: number) that returns either a Course built from the checked fields or the reason string. Type guards such as `typeof x === "string"`, Number.isInteger and a list of allowed values narrow unknown without any `as`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_412'), 3, 'A similar parser on different data, for a leaderboard row { userId: string; exp: number }: write isRecord(v: unknown): v is Record<string, unknown> (typeof v === "object", not null, not an array); then parseRow(v, i) returns "rows[i] is not an object" when !isRecord(v), reads const { userId, exp } = v, returns "rows[i].userId is invalid" unless typeof userId === "string", "rows[i].exp is invalid" unless Number.isInteger(exp), and finally returns the new object { userId, exp }. Because the result is a new object, an extra property such as "debug" never leaks into the app.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_412'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_412');
