       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_412'), 'The incident: rating renamed to averageRating, and a 503 with problem details', '[{"status":200,"headers":{"content-type":"application/json"},"body":"[{\"id\":\"c_101\",\"title\":\"React Basics\",\"category\":\"react\",\"level\":\"beginner\",\"enrolled\":1820,\"publishedAt\":\"2026-03-02T09:00:00Z\",\"averageRating\":4.6},{\"id\":\"c_305\",\"title\":\"SQL Joins Without Fear\",\"category\":\"sql\",\"level\":\"beginner\",\"enrolled\":2210,\"publishedAt\":\"2026-01-11T09:00:00Z\",\"averageRating\":4.8}]"},{"status":503,"headers":{"content-type":"application/problem+json"},"body":"{\"type\":\"about:blank\",\"title\":\"Service Unavailable\",\"status\":503,\"detail\":\"The catalog is being updated, try again in a minute.\"}"}]', '[{"ok":false,"error":{"kind":"invalid-response","reason":"courses[0].rating is invalid"}},{"ok":false,"error":{"kind":"http","status":503,"message":"The catalog is being updated, try again in a minute."}}]', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_412'), 'A network error and a timeout', '[{"error":{"name":"TypeError","message":"Failed to fetch"}},{"error":{"name":"TimeoutError","message":"signal timed out"}}]', '[{"ok":false,"error":{"kind":"network"}},{"ok":false,"error":{"kind":"timeout"}}]', 2, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_412'), 'Error messages: header case, charset, title fallback, broken problem body, HTML and plain JSON', '[{"status":404,"headers":{"Content-Type":"application/problem+json; charset=utf-8"},"body":"{\"title\":\"Not Found\",\"status\":404}"},{"status":422,"headers":{"content-type":"application/problem+json"},"body":"{\"title\":\"Unprocessable Content\",\"detail\":42}"},{"status":500,"headers":{"content-type":"application/problem+json"},"body":"{\"title\": \"Internal"},{"status":502,"headers":{"content-type":"text/html"},"body":"<html><body><h1>502 Bad Gateway</h1></body></html>"},{"status":401,"headers":{"content-type":"application/json"},"body":"{\"message\":\"invalid_token\"}"},{"status":301,"headers":{},"body":""}]', '[{"ok":false,"error":{"kind":"http","status":404,"message":"Not Found"}},{"ok":false,"error":{"kind":"http","status":422,"message":"Unprocessable Content"}},{"ok":false,"error":{"kind":"http","status":500,"message":"HTTP 500"}},{"ok":false,"error":{"kind":"http","status":502,"message":"HTTP 502"}},{"ok":false,"error":{"kind":"http","status":401,"message":"HTTP 401"}},{"ok":false,"error":{"kind":"http","status":301,"message":"HTTP 301"}}]', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_412'), 'Bodies that are not a course list: empty, whitespace, HTML, an object, null, a nested array', '[{"status":200,"headers":{"content-type":"application/json"},"body":""},{"status":200,"headers":{"content-type":"application/json"},"body":"  \n"},{"status":200,"headers":{"content-type":"text/html"},"body":"<!doctype html><html><head><title>CodeDev</title></head><body><div id=\"root\"></div></body></html>"},{"status":200,"headers":{"content-type":"application/json"},"body":"{\"items\":[{\"id\":\"c_101\",\"title\":\"React Basics\",\"category\":\"react\",\"level\":\"beginner\",\"rating\":4.6,\"enrolled\":1820,\"publishedAt\":\"2026-03-02T09:00:00Z\"}],\"total\":1}"},{"status":200,"headers":{"content-type":"application/json"},"body":"null"},{"status":200,"headers":{"content-type":"application/json"},"body":"[{\"id\":\"c_101\",\"title\":\"React Basics\",\"category\":\"react\",\"level\":\"beginner\",\"rating\":4.6,\"enrolled\":1820,\"publishedAt\":\"2026-03-02T09:00:00Z\"},null]"},{"status":200,"headers":{"content-type":"application/json"},"body":"[{\"id\":\"c_101\",\"title\":\"React Basics\",\"category\":\"react\",\"level\":\"beginner\",\"rating\":4.6,\"enrolled\":1820,\"publishedAt\":\"2026-03-02T09:00:00Z\"},[{\"id\":\"c_214\",\"title\":\"Node Streams in Practice\",\"category\":\"node\",\"level\":\"intermediate\",\"rating\":4.3,\"enrolled\":640,\"publishedAt\":\"2026-05-18T09:00:00Z\"}]]"},{"status":201,"headers":{"content-type":"application/json"},"body":"[]"}]', '[{"ok":false,"error":{"kind":"invalid-response","reason":"empty body"}},{"ok":false,"error":{"kind":"invalid-response","reason":"empty body"}},{"ok":false,"error":{"kind":"invalid-response","reason":"body is not JSON"}},{"ok":false,"error":{"kind":"invalid-response","reason":"expected an array"}},{"ok":false,"error":{"kind":"invalid-response","reason":"expected an array"}},{"ok":false,"error":{"kind":"invalid-response","reason":"courses[1] is not an object"}},{"ok":false,"error":{"kind":"invalid-response","reason":"courses[1] is not an object"}},{"ok":true,"data":[]}]', 3, false, true, 5),
