       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_412'), 'Large list: 120 courses, the 118th from an API instance that already sends averageRating', '[{"status":200,"headers":{"content-type":"application/json"},"body":"[{\"id\":\"c_1000\",\"title\":\"Course 1\",\"category\":\"react\",\"level\":\"beginner\",\"rating\":3,\"enrolled\":0,\"publishedAt\":\"2026-01-10T08:00:00Z\"},{\"id\":\"c_1001\",\"title\":\"Course 2\",\"category\":\"node\",\"level\":\"intermediate\",\"rating\":3.1,\"enrolled\":50,\"publishedAt\":\"2026-02-11T08:00:00Z\"},{\"id\":\"c_1002\",\"title\":\"Course 3\",\"category\":\"sql\",\"level\":\"advanced\",\"rating\":3.2,\"enrolled\":100,\"publishedAt\":\"2026-03-12T08:00:00Z\"},{\"id\":\"c_1003\",\"title\":\"Course 4\",\"category\":\"python\",\"level\":\"beginner\",\"rating\":3.3,\"enrolled\":150,\"publishedAt\":\"2026-04-13T08:00:00Z\"},{\"id\":\"c_1004\",\"title\":\"Course 5\",\"category\":\"devops\",\"level\":\"intermediate\",\"rating\":3.4,\"enrolled\":200,\"publishedAt\":\"2026-05-14T08:00:00Z\"},{\"id\":\"c_1005\",\"title\":\"Course 6\",\"category\":\"react\",\"level\":\"advanced\",\"rating\":3.5,\"enrolled\":250,\"publishedAt\":\"2026-06-15T08:00:00Z\"},{\"id\":\"c_1006\",\"title\":\"Course 7\",\"category\":\"node\",\"level\":\"beginner\",\"rating\":3.6,\"enrolled\":300,\"publishedAt\":\"2026-07-16T08:00:00Z\"},{\"id\":\"c_1007\",\"title\":\"Course 8\",\"category\":\"sql\",\"level\":\"intermediate\",\"rating\":3.7,\"enrolled\":350,\"publishedAt\":\"2026-08-17T08:00:00Z\"},{\"id\":\"c_1008\",\"title\":\"Course 9\",\"category\":\"python\",\"level\":\"advanced\",\"rating\":3.8,\"enrolled\":400,\"publishedAt\":\"2026-09-18T08:00:00Z\"},{\"id\":\"c_1009\",\"title\":\"Course 10\",\"category\":\"devops\",\"level\":\"beginner\",\"rating\":3.9,\"enrolled\":450,\"publishedAt\":\"2026-01-19T08:00:00Z\"},{\"id\":\"c_1010\",\"title\":\"Course 11\",\"category\":\"react\",\"level\":\"intermediate\",\"rating\":4,\"enrolled\":500,\