-- lesson 4.2: Server state as a cache: query keys & invalidation after a mutation (Sanity lesson-trf-4-2)
UPDATE course.lesson SET title = 'Server state as a cache: query keys & invalidation after a mutation', order_index = 2, module_id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend') AND order_index = 4 AND is_deleted = false LIMIT 1), updated_at = now() WHERE id = (SELECT id FROM course.lesson WHERE content_source = 'lesson-trf-4-2' AND is_deleted = false LIMIT 1);
INSERT INTO course.lesson (module_id, title, content_type, content_source, order_index)
SELECT (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend') AND order_index = 4 AND is_deleted = false LIMIT 1), 'Server state as a cache: query keys & invalidation after a mutation', 'sanity', 'lesson-trf-4-2', 2
WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-trf-4-2' AND is_deleted = false);

-- challenge chal_quiz_trf_421 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_trf_421', (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-trf-4-2' AND is_deleted = false LIMIT 1), 'query-keys-invalidation-quiz', 'Which queries does an invalidation reach?', 'Two pieces of evidence from the enrollment incident: an invalidation that never matched, and what invalidateQueries really refetches.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_trf_421');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_trf_421'), 'MyCourses.tsx:
const { data } = useQuery({ queryKey: ["enrollments", userId], queryFn: () => getEnrollments(userId) });

EnrollButton.tsx:
const enroll = useMutation({
  mutationFn: (courseId: string) => postEnrollment(courseId),
  onSuccess: () => queryClient.invalidateQueries({ queryKey: ["enrollment", userId] }),
});

Network panel after clicking Enroll on c_214 (the My courses tab is open):
POST /enrollments 201
(no GET /users/u_7/enrollments follows)

Statement: "onSuccess runs, but its key matches no cached query, because [\"enrollment\", userId] is not a prefix of [\"enrollments\", userId]; building both keys with one key factory would have prevented it."', 'single_choice'::question_type, 'True. invalidateQueries compares the filter key with each cached key element by element, from the start: "enrollment" and "enrollments" are different strings, so no query is marked stale, nothing refetches, and no error is reported. The POST succeeded, which is why the button looked fine and only the other tab was wrong. A key factory (enrollmentKeys.byUser(userId)) used by both useQuery and the invalidation turns a typo into a compile error or makes it impossible. The misconception is that an invalidation that matches nothing fails loudly; it silently does nothing.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_trf_421') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_trf_421'), 'After saving a course in the admin page:

await queryClient.invalidateQueries({ queryKey: ["courses"] });

TanStack Query Devtools just before the call:
["courses","list",{"category":"react"}]   1 observer   (on screen)
["courses","list",{"category":"node"}]    0 observers  (inactive)
["courses","detail","c_214"]               0 observers  (inactive)

Statement: "With the default options, this call immediately sends three GET requests, one for each cached query under [\"courses\"]."', 'single_choice'::question_type, 'False. In TanStack Query v5, invalidateQueries marks every matching query as stale, but by default (refetchType: "active") it refetches only the queries that are currently rendered, here the react list: one GET. The two inactive queries stay in the cache marked stale and refetch when a component uses them again. So a broad invalidation is cheaper than it looks on a quiet page and expensive on a dashboard with many mounted queries, which is how the over-eager fix reached 40 requests per click. Check it in the Network panel and in Devtools, where invalidated queries turn stale. The misconception is that invalidate means refetch everything now.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_trf_421') AND order_index = 2)
    RETURNING id
)
