-- challenge chal_coding_trf_422 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_trf_422', (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-trf-4-2' AND is_deleted = false LIMIT 1), 'query-keys-invalidation', 'Query key factory and invalidation after a mutation', 'After a learner enrolled, the catalog''s My courses tab kept showing Enroll until a full reload; the first fix invalidated every query after every mutation and refetched 40 queries per click. Write the key factories and keysToInvalidate. (1) normalizeFilters(filters) turns URL filters into a canonical object: keep category only if it is react, node, sql, python or devops; level only if beginner, intermediate or advanced; page only if it is an integer greater than 1 (page 1 is the default); search trimmed and lower-cased, only if not empty; sort only if it is newest or rating (popular is the default; any other value is dropped). Every other property is dropped. Add the kept properties in alphabetical order (category, level, page, search, sort), so equal filters give identical keys. (2) courseKeys.all = ["courses"], courseKeys.lists() = ["courses", "list"], courseKeys.list(filters) = ["courses", "list", normalizeFilters(filters)], courseKeys.details() = ["courses", "detail"], courseKeys.detail(id) = ["courses", "detail", id], enrollmentKeys.all = ["enrollments"], enrollmentKeys.byUser(userId) = ["enrollments", userId]. (3) keysToInvalidate(cachedKeys, mutation) returns the cached keys, in cache order, that start with one of the mutation''s target keys, compared element by element (an element matches when it is deep-equal; a longer cached key below a target matches too, a string that merely begins with the same characters does not). Targets: enroll and unenroll -> courseKeys.detail(courseId) and enrollmentKeys.byUser(userId) (lists are not invalidated: catalog cards may show the enrolled count up to a minute late); edit -> courseKeys.detail(courseId), courseKeys.lists() and enrollmentKeys.all (My courses shows titles); publish -> courseKeys.lists(); any other mutation type -> nothing. The runner prints courseKeys.list(f) for each f of { "filters": [...] }, or keysToInvalidate(cache, m) for each m of { "cache": [...], "mutations": [...] }, as JSON.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
