-- challenge chal_quiz_trf_431 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_trf_431', (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-trf-4-3' AND is_deleted = false LIMIT 1), 'debounced-search-quiz', 'Stale responses and fake timers', 'Two pieces of evidence from the search incident: a slow response that arrived last, and a test that checks a 300 ms debounce in a few milliseconds.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
