    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_trf_431'), 'A Vitest test for the debounced search hook (debounce 300 ms):

vi.useFakeTimers();
const search = vi.fn().mockResolvedValue([]);
const box = createDebouncedSearch({ debounceMs: 300, search, ... });
box.onInput("react");
vi.advanceTimersByTime(299);
expect(search).toHaveBeenCalledTimes(0);   // passes
vi.advanceTimersByTime(1);
expect(search).toHaveBeenCalledTimes(1);   // passes

 Test Files  1 passed (1)
 Duration  41ms

Statement: "Because the whole test runs in 41 ms, it cannot prove the 300 ms delay; only a test that really waits 300 ms can check the debounce."', 'single_choice'::question_type, 'False. Fake timers replace setTimeout with a clock the test moves by hand, so time in the code under test is exactly the time the test advances: at 299 ms the timer has not fired, at 300 ms it has. That pins the boundary to the millisecond, deterministically, which a real 300 ms wait cannot do (a slow CI machine fires late, and the test cannot tell 299 from 320). What fake timers do not prove is how the real browser schedules timers, which is not what this test is about. The misconception is that a test about time has to spend real time.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_trf_431') AND order_index = 2)
    RETURNING id
)
