    ) AS o(option_text, is_correct);

-- challenge chal_coding_trf_432 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_trf_432', (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-trf-4-3' AND is_deleted = false LIMIT 1), 'debounced-search', 'Debounced search that cancels stale requests', 'Typing "react hooks" quickly in the catalog search box sent 11 requests, and the slow response for "re" arrived last and replaced the right results. Write createDebouncedSearch({ clock, debounceMs, search, show, showError }), which returns { onInput(text), dispose() }. Rules: (1) Every onInput cancels the pending timer, if any. (2) If text.trim() is empty: do not send anything, abort the in-flight request if there is one, and call show([]) at once. (3) Otherwise start a timer with clock.setTimeout for debounceMs; when it fires, abort the previous in-flight request (if any) first, then call search(text.trim(), signal) with the signal of a new FakeAbortController. (4) Only the latest request may update the screen: when it resolves, call show(results); when it rejects with an error whose name is not "AbortError", call showError(error.message). A request stops being the latest as soon as a newer request is sent, the box is cleared (rule 2) or dispose is called; its later response or error is ignored, even when the server ignored the abort and answered anyway. An earlier response that arrives while a new timer is still pending is still the latest, so it is shown. (5) dispose() (the component unmounts) cancels the pending timer and aborts the in-flight request; nothing is shown afterwards. Use only the injected clock (no setTimeout, no Date). The runner replays a timeline - { "input": text }, { "type": chars, "every": ms }, { "advance": ms }, { "unmount": true } - against a fake API with per-query latencies, some queries that ignore abort and some that fail with HTTP 503, runs the clock 10 more seconds at the end, and prints the event log: requests, aborts, responses, what was shown and errors, each with its time.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_432');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_432'), 1, 'Three separate jobs hide in this box: deciding when to send (the timer), stopping the network work that is no longer needed (abort), and deciding whether an answer may still reach the screen. Which of the three protects you when the server ignores the abort?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_432'), 2, 'Keep three variables in the closure returned by createDebouncedSearch: the pending timer id, the controller of the in-flight request, and a counter or id of the latest request. Look at what each of onInput, the timer callback, the .then handlers and dispose has to read or change; the handlers compare the id they captured with the current latest one.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_432'), 3, 'A similar pattern on a different feature, autosave of a lesson note with a 1 s delay: onChange clears the pending timer and starts a new one; when it fires, saveCount += 1 and the save captures const mine = saveCount; when its response arrives, it updates the "Saved" label only if mine === saveCount, so an older save that finishes late never overwrites the status of a newer one.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_432'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
