       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_432'), 'A slow "re" is aborted when "react" is sent, so it never replaces the results', '{"debounceMs":300,"latency":{"re":900,"react":200},"steps":[{"input":"re"},{"advance":400},{"input":"react"}]}', '["t=300 request \"re\"","t=700 abort \"re\"","t=700 request \"react\"","t=900 response \"react\"","t=900 show [React Basics, React Hooks in Depth, Testing React Hooks with Fake Timers, TypeScript for React Developers]"]', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_432'), 'The server ignores the abort: the late "re" response arrives but is never shown', '{"debounceMs":300,"latency":{"re":900,"react":200},"ignoresAbort":["re"],"steps":[{"input":"re"},{"advance":400},{"input":"react"}]}', '["t=300 request \"re\"","t=700 abort \"re\" (ignored by the server)","t=700 request \"react\"","t=900 response \"react\"","t=900 show [React Basics, React Hooks in Depth, Testing React Hooks with Fake Timers, TypeScript for React Developers]","t=1200 response \"re\""]', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_432'), 'Clearing the box: results cleared at once, in-flight request aborted, pending timer dropped', '{"debounceMs":300,"latency":{"sql":500},"ignoresAbort":["sql"],"steps":[{"input":"sql"},{"advance":350},{"input":"   "},{"advance":100},{"input":"no"},{"advance":100},{"input":""}]}', '["t=300 request \"sql\"","t=350 abort \"sql\" (ignored by the server)","t=350 show []","t=550 show []","t=800 response \"sql\""]', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_432'), 'Errors: the latest request''s HTTP 503 is shown, a stale request''s error is not', '{"debounceMs":300,"latency":{"py":700},"ignoresAbort":["py"],"failing":["py","sql"],"steps":[{"input":"py"},{"advance":400},{"input":"python"},{"advance":1000},{"input":"sql"}]}', '["t=300 request \"py\"","t=700 abort \"py\" (ignored by the server)","t=700 request \"python\"","t=900 response \"python\"","t=900 show [Python for Data Pipelines]","t=1000 response \"py\"","t=1700 request \"sql\"","t=1900 response \"sql\"","t=1900 error HTTP 503"]', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_432'), 'Unmount with a pending timer and a request in flight: nothing is sent or shown afterwards', '{"debounceMs":300,"latency":{"node":400},"steps":[{"input":"node"},{"advance":350},{"input":"nodejs"},{"advance":100},{"unmount":true}]}', '["t=300 request \"node\"","t=450 abort \"node\"","t=450 unmount"]', 2, false, true, 6),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_trf_432'), 'Long session: leading spaces, pauses, a response during typing, out-of-order latencies', '{"debounceMs":250,"defaultLatency":150,"latency":{"react":300,"react hooks":800,"typescript for react":500},"ignoresAbort":["react hooks"],"steps":[{"type":"  react","every":60},{"advance":300},{"type":" hooks","every":100},{"advance":260},{"type":" with","every":70},{"advance":400},{"input":""},{"advance":50},{"type":"typescript for react developers","every":40},{"advance":100},{"input":"typescript for react"},{"advance":300},{"input":"typescript for react developers"}]}', '["t=0 show []","t=60 show []","t=610 request \"react\"","t=910 response \"react\"","t=910 show [React Basics, React Hooks in Depth, Testing React Hooks with Fake Timers, TypeScript for React Developers]","t=1470 request \"react hooks\"","t=2110 abort \"react hooks\" (ignored by the server)","t=2110 request \"react hooks with\"","t=2260 response \"react hooks with\"","t=2260 show [Testing React Hooks with Fake Timers]","t=2270 response \"react hooks\"","t=2330 show []","t=3970 request \"typescript for react\"","t=4270 abort \"typescript for react\"","t=4270 request \"typescript for react developers\"","t=4420 response \"typescript for react developers\"","t=4420 show [TypeScript for React Developers]"]', 3, false, true, 7);

-- learners enrolled before these lessons existed
INSERT INTO learning.history (user_id, course_id, module_id, lesson_id)
SELECT r.user_id, r.course_id, m.id, l.id
FROM learning.register r
JOIN course.module m ON m.course_id = r.course_id AND m.is_deleted = false
JOIN course.lesson l ON l.module_id = m.id AND l.is_deleted = false
WHERE r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend') AND r.is_deleted = false
ON CONFLICT DO NOTHING;
WITH ordered AS (
    SELECT h.user_id, h.lesson_id, h.status,
           row_number() OVER (PARTITION BY h.user_id ORDER BY m.order_index, l.order_index) AS rn
    FROM learning.history h
    JOIN course.lesson l ON l.id = h.lesson_id AND l.is_deleted = false
    JOIN course.module m ON m.id = l.module_id AND m.is_deleted = false
    WHERE h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend')
),
next_lesson AS (
    SELECT DISTINCT ON (o.user_id) o.user_id, o.lesson_id
    FROM ordered o
    WHERE o.status = 'enrolled'
      AND NOT EXISTS (SELECT 1 FROM ordered p WHERE p.user_id = o.user_id AND p.rn < o.rn AND p.status <> 'completed')
    ORDER BY o.user_id, o.rn
)
UPDATE learning.history h
SET status = 'in_progress', updated_at = now()
FROM next_lesson n
JOIN learning.register r ON r.user_id = n.user_id AND r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend') AND r.is_deleted = false AND r.status <> 'enrolled'
WHERE h.user_id = n.user_id AND h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend') AND h.lesson_id = n.lesson_id;
UPDATE learning.register r
SET status = 'in_progress'
WHERE r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend') AND r.status = 'completed'
  AND EXISTS (SELECT 1 FROM learning.history h WHERE h.user_id = r.user_id AND h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-react-frontend') AND h.status <> 'completed');

COMMIT;
